const cfg = $('Definir Destinatário').first().json;
const entrada = $input.first().json || {};

if (!/^[^@\s]+@(c|g)\.us$/.test(cfg.chatId)) {
  throw new Error('chatId inválido no node "Definir Destinatário" — use seu número (55+DDD+número @c.us) ou o ID de um grupo (@g.us). Grupo: GET http://localhost:3000/api/{sessao}/groups');
}

const ex = entrada.execution || {};
const err = ex.error || {};
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Execução manual do próprio alerta (ou exemplo do Error Trigger) = teste
const ehTeste = !ex.error || ex.mode === 'manual';

let texto;
if (ehTeste) {
  texto = '🧪 *Teste do alerta de falha*\n\n' +
    '📅 ' + agora + '\n' +
    'Tudo certo por aqui — este é apenas um teste manual do alerta.';
} else {
  const detalhes = [err.message, err.description].filter(Boolean).join(' — ') || 'sem detalhes';
  texto = '❌ *Falha no robô do clima*\n\n' +
    '📅 ' + agora + '\n' +
    '🧩 Workflow: ' + ((entrada.workflow && entrada.workflow.name) || '?') + '\n' +
    '📍 Nó: ' + (ex.lastNodeExecuted || '?') + '\n\n' +
    '⚠️ ' + detalhes;
}

return [{ json: { body: { session: cfg.session, chatId: cfg.chatId, text: texto } } }];
